package com.obysoft.faithOS.controller;
import java.util.List;import org.springframework.http.*;import org.springframework.web.bind.annotation.*;import org.springframework.security.access.prepost.PreAuthorize;import com.obysoft.faithOS.dto.*;import com.obysoft.faithOS.service.EventService;import jakarta.validation.Valid;
@RestController @RequestMapping("/api/events") public class EventController{private final EventService service;public EventController(EventService service){this.service=service;}@GetMapping public List<EventResponse> all(){return service.all();}@PostMapping @PreAuthorize("hasAnyRole('SUPER_ADMIN','CHURCH_ADMIN','PASTOR','LEADER')") public ResponseEntity<EventResponse> create(@Valid @RequestBody EventRequest r){return ResponseEntity.status(HttpStatus.CREATED).body(service.create(r));}@PutMapping("/{id}") @PreAuthorize("hasAnyRole('SUPER_ADMIN','CHURCH_ADMIN','PASTOR','LEADER')") public EventResponse update(@PathVariable Long id,@Valid @RequestBody EventRequest r){return service.update(id,r);}@DeleteMapping("/{id}") @PreAuthorize("hasAnyRole('SUPER_ADMIN','CHURCH_ADMIN','PASTOR','LEADER')") @ResponseStatus(HttpStatus.NO_CONTENT) public void delete(@PathVariable Long id){service.delete(id);}}
